const now = new Date();
const month = now.getMonth() + 1;
const day = now.getDate();

// Key dates for Morocco education calendar
const events = [
  // Fixed dates
  { month: 1, day: 1, name: 'New Year', daysAhead: 7, type: 'holiday' },
  { month: 7, day: 30, name: 'Throne Day', daysAhead: 7, type: 'cultural' },
  { month: 2, day: 14, name: 'Valentine\'s Day', daysAhead: 5, type: 'social' },
  { month: 3, day: 8, name: 'Women\'s Day', daysAhead: 5, type: 'social' },
  { month: 3, day: 20, name: 'Spring Break Start', daysAhead: 7, type: 'school' },
  { month: 5, day: 1, name: 'Labour Day', daysAhead: 3, type: 'holiday' },
  { month: 5, day: 15, name: 'BAC Exam Prep Season', daysAhead: 14, type: 'exam' },
  { month: 6, day: 1, name: 'Children\'s Day', daysAhead: 5, type: 'social' },
  { month: 6, day: 10, name: 'BAC Exams Start', daysAhead: 10, type: 'exam' },
  { month: 6, day: 15, name: 'Brevet Exams', daysAhead: 10, type: 'exam' },
  { month: 7, day: 30, name: 'Independence Day', daysAhead: 5, type: 'holiday' },
  { month: 9, day: 1, name: 'Back to School', daysAhead: 14, type: 'school' },
  { month: 9, day: 21, name: 'School Year Start', daysAhead: 7, type: 'school' },
  { month: 10, day: 5, name: 'Teacher\'s Day', daysAhead: 5, type: 'social' },
  { month: 11, day: 6, name: 'Green March Anniversary', daysAhead: 3, type: 'holiday' },
  { month: 12, day: 15, name: 'Winter Break', daysAhead: 7, type: 'school' },
  // Semester exams (approximate)
  { month: 1, day: 15, name: 'First Semester Exams', daysAhead: 10, type: 'exam' },
  { month: 3, day: 10, name: 'Second Trimester Exams', daysAhead: 10, type: 'exam' },
  { month: 5, day: 20, name: 'Third Trimester Exams', daysAhead: 10, type: 'exam' }
];

// Check what's coming up in the next 7 days
const upcoming = events.filter(e => {
  const eventDate = new Date(now.getFullYear(), e.month - 1, e.day);
  const daysUntil = Math.ceil((eventDate - now) / (1000 * 60 * 60 * 24));
  return daysUntil > 0 && daysUntil <= e.daysAhead;
}).map(e => {
  const eventDate = new Date(now.getFullYear(), e.month - 1, e.day);
  const daysUntil = Math.ceil((eventDate - now) / (1000 * 60 * 60 * 24));
  return { ...e, daysUntil };
});

if (upcoming.length === 0) {
  return [{ json: { hasEvent: false } }];
}

return [{ json: { hasEvent: true, events: upcoming, today: now.toISOString() } }];

